        private void CreateInvoiceModelObjectFields(Dictionary<string, ObjectField> objectFields, Dictionary<string, TextCode> textCodes)
        {
            // AR Invoice
            CreateARInvoiceFields(objectFields, textCodes);
            CreateARInvoiceLineFields(objectFields, textCodes);
            CreateARInvoiceTypeFields(objectFields, textCodes);
            CreateARInvoiceStatusFields(objectFields, textCodes);
            CreateARInvoicePaymentFields(objectFields, textCodes);
            CreateARInvoiceTransferStatusFields(objectFields, textCodes);
            CreateARInvoiceLineActionFields(objectFields, textCodes);    

            // AP Invoice
            CreateAPInvoiceFields(objectFields, textCodes);
            CreateAPInvoiceLineFields(objectFields, textCodes);
            CreateAPInvoiceTotalVatsFields(objectFields, textCodes);
            CreateAPInvoiceTypeFields(objectFields, textCodes);
            CreateAPInvoiceStatusFields(objectFields, textCodes);
            CreateAPInvoicePaymentFields(objectFields, textCodes);
            CreateAPInvoiceTransferStatusFields(objectFields, textCodes);

            // AR Payment
            CreateARPaymentFields(objectFields, textCodes);
            CreateAccountingPaymentMethodFields(objectFields, textCodes);
            CreateARPaymentStatusFields(objectFields, textCodes);
            CreateARPaymentTransferStatusFields(objectFields, textCodes);

            // AP Payment
            CreateAPPaymentFields(objectFields, textCodes);
            CreateAPPaymentMethodFields(objectFields, textCodes);
            CreateAPPaymentStatusFields(objectFields, textCodes);
            CreateAPPaymentTransferStatusFields(objectFields, textCodes);

            CreateBankAccountLiteFields(objectFields, textCodes);
            CreateSATTransferStatusFields(objectFields, textCodes);
            CreateSATInvoiceStatusFields(objectFields, textCodes);
        }

